import {esc,fmt} from '../../ui/format.js';
import {TYPES,FIELDS,PROCESS,POOLS,effective} from '../../core/model.js';
import {DIAGRAMS,expandedNeeds,modelAudit} from '../../core/mbse.js';
import {RELATIONS} from '../../core/model.js';
export function resultsView(ctx){const {m,result,baseline,search}=ctx;const n=id=>m.nodes.find(n=>n.id===id);if(!result)return `<h1>Simulare integrată</h1><div class="panel empty">Construiește o rută Sursă → Operație → Produs final, alocă resursele și rulează modelul.</div>`;const r=result.first;return `<div class="panelhead"><h1>Rezultatele modelului</h1><div class="row"><button data-action="results-json">↓ Raport JSON</button><button data-action="results-csv">↓ Operații CSV</button></div></div><div class="stats">${[['Produse bune',fmt(r.good,0)],['Rebut / WIP',fmt(r.scrap,0)+' / '+fmt(r.wip,0)],['Lead time mediu',r.leadMean==null?'—':fmt(r.leadMean/60)+' min'],['Cost modelat',fmt(r.totalCost)+' €']].map(([a,b])=>`<div class="stat"><span class="muted small">${a}</span><div class="value">${b}</div></div>`).join('')}</div><div class="notice">${result.runs.length} replicări · medie produse bune ${fmt(result.mean)} ${result.ci95==null?'· fără interval de încredere':`± ${fmt(result.ci95)} (IC 95% aproximativ, Student t)`}. Tabelele detaliate reprezintă prima replicare. Intrări ${r.arrived} = bune ${r.good} + rebut ${r.scrap} + WIP ${r.wip}. Lead time include doar piesele finalizate.</div><div class="panel"><h2>Ieșiri pe flux</h2><p class="small muted">Totalul agregă toate ieșirile, inclusiv subansamblele; nu echivalează cu numărul de sisteme finale.</p><div class="row">${r.outputs.map(x=>`<span class="pill">${esc(x.name)}: ${fmt(x.good,0)}</span>`).join('')}</div></div><div class="panel tablewrap"><h2>Operații · stări și cauze de așteptare</h2><table><thead><tr><th>Operație</th><th>Procesare / defect / blocat / idle</th><th>Coadă medie</th><th>Așteptare resursă</th><th>Lipsă material</th><th>Calendar închis</th></tr></thead><tbody>${r.operations.map(o=>`<tr><td>${esc(o.name)}</td><td><div class="bar"><i class="busy" style="width:${o.busy*100}%"></i><i style="background:#c96959;width:${o.down*100}%"></i><i class="blocked" style="width:${o.blocked*100}%"></i><i class="idle" style="width:${o.idle*100}%"></i></div><small>${fmt(o.busy*100)}% / ${fmt(o.down*100)}% / ${fmt(o.blocked*100)}% / ${fmt(o.idle*100)}%</small></td><td>${fmt(o.queue)}</td><td>${fmt(o.resourceWait/60)} min</td><td>${fmt(o.materialWait/60)} min</td><td>${fmt(o.calendarWait/60)} min</td></tr>`).join('')}</tbody></table></div><div class="grid2"><div class="panel"><h2>Personal, HW, SW și resurse comune</h2><table><thead><tr><th>Resursă</th><th>Ocupare / orizont</th><th>Cost</th></tr></thead><tbody>${r.resources.map(x=>`<tr><td>${esc(x.name)}</td><td>${fmt(x.utilization*100)}%</td><td>${fmt(x.cost)} €</td></tr>`).join('')}</tbody></table></div><div class="panel"><h2>Materiale & energie</h2><table><thead><tr><th>Material</th><th>Produs</th><th>Consum</th><th>Stoc rămas</th></tr></thead><tbody>${r.materials.map(x=>`<tr><td>${esc(x.name)}</td><td>${fmt(x.produced)}</td><td>${fmt(x.consumed)}</td><td>${fmt(x.remaining)}</td></tr>`).join('')}</tbody></table><p>${fmt(r.energy)} kWh în procesare · ${fmt(r.materialCost)} € materiale</p><p class="small muted">Costurile sunt cele parametrizate, fără salarii fixe, tarife energetice sau amortizare implicite.</p></div></div>${r.warnings.length?`<div class="notice">${r.warnings.map(esc).join('<br>')}</div>`:''}<div class="notice">Pentru confirmarea unui bottleneck, salvează baseline-ul și compară o schimbare izolată. Ocuparea mare nu este singură dovada constrângerii.</div>`}
